import json, re, html
from pathlib import Path
S=json.loads(Path('source.json').read_text())
R=json.loads(Path('reference-targets.json').read_text())
OUT=[]

def plain(x):
    return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]*>',' ',x or ''))).strip()

def paragraphs(*parts):
    return '\n'.join('<p>'+html.escape(p,quote=False)+'</p>' for p in parts)

def impact(classification,assessment,limits,burdens,effects):
    return dict(version=1,classification=classification,assessment=assessment,scope_limitations=limits,new_burdens_review=burdens,effects=effects)

def effect(kind,measure,description,before,after,unit,pop,transition,replacement,source_quote,proposed_quote):
    return dict(kind=kind,measure_id=measure,description=description,before=before,after=after,unit=unit,affected_population=pop,conditions_and_transition=transition,replacement_or_new_burdens=replacement,source_quote=source_quote,proposed_quote=proposed_quote)

def obj(i,xml,reason,notes,imp,removed=None,repeal=None,benefit=None):
    s=S[i]
    a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=xml,reason=reason,review_notes=notes,status='rewrite_draft',substantive_impact=imp)
    if xml is None:a['status']='retained_unchanged'
    if removed:a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    if repeal:a.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=repeal)
    if benefit:a['benefit_review']=benefit
    OUT.append(a)
    return a

